const ctx = $('1. Validation payload').first().json;
const res = $input.first().json || {};

const UNITES = ['Fft','U','pce','m2','ml','h'];
const normUnite = (u) => {
  if (!u) return 'Fft';
  if (UNITES.includes(u)) return u;
  const m = String(u).toLowerCase().replace('²','2').trim();
  const map = {
    'm2':'m2','ml':'ml','m':'ml','h':'h','heure':'h','heures':'h',
    'u':'U','unite':'U','unité':'U',
    'pce':'pce','piece':'pce','pièce':'pce','pieces':'pce','pièces':'pce',
    'fft':'Fft','forfait':'Fft','bl':'Fft','bloc':'Fft','forf':'Fft'
  };
  return map[m] || 'Fft';
};

// Extraire le contenu de la réponse API /v1/responses
let content = res?.output?.[0]?.content?.[0]?.text ||
  res?.choices?.[0]?.message?.content ||
  res?.content || res?.text || null;

let raw;
if (content && typeof content === 'object') {
  raw = content;
} else if (typeof content === 'string') {
  try { raw = JSON.parse(content.replace(/^```(json)?/m,'').replace(/```\s*$/m,'').trim()); }
  catch(e) { return [{ json: { ok: false, erreur: 'extraction_echouee' } }]; }
} else {
  return [{ json: { ok: false, erreur: 'extraction_echouee' } }];
}

if (!Array.isArray(raw.lignes) || raw.lignes.length === 0) {
  return [{ json: { ok: false, erreur: 'aucune_ligne_extraite' } }];
}

const avertissements = Array.isArray(raw.avertissements) ? raw.avertissements.map(a => String(a)).slice(0,10) : [];
const lignes = [];

for (const l of raw.lignes) {
  if (!l || typeof l !== 'object') continue;
  const designation = String(l.designation || '').trim().slice(0, 300);
  if (!designation || designation.length < 3) continue;
  // Exclure les totaux/sous-totaux résiduels
  if (/^(total|sous-total|montant|tva|ttc|ht net|sous total)/i.test(designation)) continue;
  const unite = normUnite(l.unite);
  const quantite = parseFloat(String(l.quantite || '0').replace(/[^0-9.,]/g,'').replace(',','.')) || 0;
  const prix_unitaire = parseFloat(String(l.prix_unitaire || '0').replace(/[^0-9.,]/g,'').replace(',','.')) || 0;
  // Garder même si quantite ou prix = 0 (l'utilisateur corrigera)
  lignes.push({ designation, unite, quantite, prix_unitaire });
}

if (lignes.length === 0) {
  return [{ json: { ok: false, erreur: 'aucune_ligne_valide' } }];
}

return [{ json: {
  ok: true,
  fournisseur: String(raw.fournisseur || '').trim() || null,
  lignes,
  avertissements
} }];
